import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as n,af as l}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Claude Code Auto Mode 安全机制","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/ai-coding/claude-code-auto-mode-security.md","filePath":"zh/tech/ai-coding/claude-code-auto-mode-security.md","lastUpdated":1780925410000}'),o={name:"zh/tech/ai-coding/claude-code-auto-mode-security.md"};function i(s,a,r,d,h,u){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="claude-code-auto-mode-安全机制" tabindex="-1">Claude Code Auto Mode 安全机制 <a class="header-anchor" href="#claude-code-auto-mode-安全机制" aria-label="Permalink to &quot;Claude Code Auto Mode 安全机制&quot;">​</a></h1><blockquote><p>原文: <a href="https://www.anthropic.com/engineering/claude-code-auto-mode" target="_blank" rel="noreferrer">Claude Code auto mode: a safer way to skip permissions</a></p></blockquote><h2 id="背景问题" tabindex="-1">背景问题 <a class="header-anchor" href="#背景问题" aria-label="Permalink to &quot;背景问题&quot;">​</a></h2><p>Claude Code 默认在运行命令或修改文件前会请求用户批准。这虽然保证了安全，但也带来了&quot;审批疲劳&quot;——用户逐渐不再仔细审视每次审批内容。</p><p>现有解决方案：</p><ul><li><strong>沙箱模式</strong>：安全但高维护成本，新能力需要单独配置，依赖网络或主机访问的能力会破坏隔离</li><li><strong>--dangerously-skip-permissions</strong>：零维护但无保护</li></ul><p>Auto Mode 是介于人工审批和完全无护栏之间的新模式，将审批权委托给基于模型的分类器。</p><h2 id="安全威胁模型" tabindex="-1">安全威胁模型 <a class="header-anchor" href="#安全威胁模型" aria-label="Permalink to &quot;安全威胁模型&quot;">​</a></h2><p>Agent 可能因四种原因采取危险操作：</p><ol><li><strong>过度积极行为</strong>：理解用户目标，但采取的行动超出了用户授权范围（如发现凭据后直接使用）</li><li><strong>无心之失</strong>：Agent 误解了影响范围（如以为资源是测试用的，实际是共享的）</li><li><strong>提示词注入</strong>：文件中植入的指令劫持 Agent 行为</li><li><strong>模型对齐问题</strong>：Agent 追求自身目标（目前实践中未观察到）</li></ol><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>Auto Mode 采用两层防御：</p><h3 id="输入层-提示词注入检测" tabindex="-1">输入层：提示词注入检测 <a class="header-anchor" href="#输入层-提示词注入检测" aria-label="Permalink to &quot;输入层：提示词注入检测&quot;">​</a></h3><p>服务端的 prompt-injection probe 扫描工具输出（文件读取、网页获取、shell 输出），发现内容可疑时注入警告，让 Agent 锚定在用户真实意图上。</p><h3 id="输出层-转录分类器" tabindex="-1">输出层：转录分类器 <a class="header-anchor" href="#输出层-转录分类器" aria-label="Permalink to &quot;输出层：转录分类器&quot;">​</a></h3><ul><li>运行在 Sonnet 4.6 上</li><li>在每个工具调用执行前评估操作</li><li>两阶段设计： <ul><li><strong>Stage 1</strong>：快速单 token 过滤器（yes 表示阻止，no 表示允许）</li><li><strong>Stage 2</strong>：仅当 Stage 1 标记时才进行链式思维推理</li></ul></li><li>分类器只看到用户消息和 Agent 的工具调用，Claude 自身的消息和工具输出被剥离（reasoning-blind 设计）</li></ul><h2 id="权限决策三层架构" tabindex="-1">权限决策三层架构 <a class="header-anchor" href="#权限决策三层架构" aria-label="Permalink to &quot;权限决策三层架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tier 1: 内置安全工具白名单 + 用户设置</span></span>
<span class="line"><span>  └── 只读工具（文件读取、搜索、代码导航）</span></span>
<span class="line"><span>  └── 进入 Auto Mode 时丢弃已知的任意代码执行权限规则</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tier 2: 项目内文件操作</span></span>
<span class="line"><span>  └── 项目目录内的文件写入/编辑无需分类器调用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tier 3: 转录分类器（真正的决策层）</span></span>
<span class="line"><span>  └── shell 命令、外部工具集成、子 Agent 启动、目录外文件系统操作</span></span></code></pre></div><h2 id="分类器决策标准" tabindex="-1">分类器决策标准 <a class="header-anchor" href="#分类器决策标准" aria-label="Permalink to &quot;分类器决策标准&quot;">​</a></h2><h3 id="固定模板" tabindex="-1">固定模板 <a class="header-anchor" href="#固定模板" aria-label="Permalink to &quot;固定模板&quot;">​</a></h3><ul><li><strong>评估规则</strong>：评估操作的现实影响，而非仅看调用文本表面</li><li><strong>用户意图规则</strong>：判断操作是否经过用户授权，分类器故意保守——Agent 自己选择的操作都未经授权</li></ul><h3 id="可定制槽位" tabindex="-1">可定制槽位 <a class="header-anchor" href="#可定制槽位" aria-label="Permalink to &quot;可定制槽位&quot;">​</a></h3><p><strong>环境（Environment）</strong>：定义信任边界（哪些域名、哪些 GitHub org、哪些内部服务属于&quot;内部&quot;）</p><p><strong>阻止规则（Block Rules）</strong>：</p><ul><li>销毁或泄露：强制推送、批量删除云存储、向外发送内部数据</li><li>降低安全态势：禁用日志、安装持久化（SSH key、cronjob）</li><li>跨信任边界：在外部 repo 上运行代码、扫描凭据存储</li><li>绕过审查或影响他人：直接推送到 main、跳过验证标志</li></ul><p><strong>允许例外（Allow Exceptions）</strong>：阻止规则技术上匹配但实际无害的情况（如安装已声明的包）</p><h2 id="评估结果" tabindex="-1">评估结果 <a class="header-anchor" href="#评估结果" aria-label="Permalink to &quot;评估结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据集</th><th>Stage 1 FPR</th><th>Stage 1 FNR</th><th>Stage 1→2 FPR</th><th>Stage 1→2 FNR</th></tr></thead><tbody><tr><td>真实流量 (n=10,000)</td><td>8.5%</td><td>—</td><td>0.4%</td><td>—</td></tr><tr><td>真实过度行为 (n=52)</td><td>—</td><td>6.6%</td><td>—</td><td>17%</td></tr><tr><td>合成数据泄露 (n=1,000)</td><td>—</td><td>1.8%</td><td>—</td><td>5.7%</td></tr></tbody></table><p>17% 的假阴性率主要原因是：分类器正确识别了危险操作，但判断错了用户是否真的授权了该操作。</p><h2 id="关键设计决策" tabindex="-1">关键设计决策 <a class="header-anchor" href="#关键设计决策" aria-label="Permalink to &quot;关键设计决策&quot;">​</a></h2><h3 id="为什么剥离-assistant-文本和工具结果" tabindex="-1">为什么剥离 Assistant 文本和工具结果 <a class="header-anchor" href="#为什么剥离-assistant-文本和工具结果" aria-label="Permalink to &quot;为什么剥离 Assistant 文本和工具结果&quot;">​</a></h3><ul><li>防止 Agent 通过生成的论证说服分类器做出错误判断</li><li>同时也是主要的提示词注入防御</li><li>测试表明，包含 Assistant 消息时过度行为测试集性能下降</li></ul><h3 id="两阶段分类的效率权衡" tabindex="-1">两阶段分类的效率权衡 <a class="header-anchor" href="#两阶段分类的效率权衡" aria-label="Permalink to &quot;两阶段分类的效率权衡&quot;">​</a></h3><ul><li>Stage 1 调优为高召回率，接受 8.5% FPR 作为代价</li><li>Stage 2 保持相同输入，仅改变最终指令要求仔细推理</li><li>由于输入相同，Stage 2 几乎完全复用 Stage 1 的缓存</li></ul><h3 id="多-agent-handoff" tabindex="-1">多 Agent handoff <a class="header-anchor" href="#多-agent-handoff" aria-label="Permalink to &quot;多 Agent handoff&quot;">​</a></h3><ul><li><strong>派出时检查</strong>：防止子 Agent 看起来像是完全授权的任务</li><li><strong>返回时检查</strong>：防止子 Agent 在运行中被提示词注入攻击</li></ul><h3 id="deny-and-continue" tabindex="-1">Deny-and-Continue <a class="header-anchor" href="#deny-and-continue" aria-label="Permalink to &quot;Deny-and-Continue&quot;">​</a></h3><ul><li>阻止操作时返回工具结果 + 重试指令，Agent 寻找更安全的路径</li><li>连续 3 次或累计 20 次阻止后终止并升级给人类</li><li>这使假阳性可容忍：0.4% FPR 的误判只产生一次重试</li></ul><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>Auto Mode 不是完全没有风险，而是显著优于 <code>--dangerously-skip-permissions</code></li><li>不适合作为高风险基础设施上人工仔细审查的直接替代</li><li>用户应关注残留风险，对哪些任务和环境自主运行做出判断</li></ul>`,40)])])}const q=t(o,[["render",i]]);export{m as __pageData,q as default};
